@Composable
private fun BrowserLayoutMock(position: ToolbarPosition, compact: Boolean) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .height(if (compact) 132.dp else 160.dp),
        shape = RoundedCornerShape(IlyroVisualTokens.SmallRadius),
        color = MaterialTheme.colorScheme.background,
        border = BorderStroke(
            1.dp,
            MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.12f)
        ),
        tonalElevation = 0.dp,
        shadowElevation = 0.dp
    ) {
        Column(modifier = Modifier.fillMaxSize().padding(7.dp)) {
            if (position == ToolbarPosition.TOP) {
                FakeToolbar()
                Spacer(modifier = Modifier.height(7.dp))
            }
            Surface(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth(),
                shape = RoundedCornerShape(11.dp),
                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.42f)
            ) {
                Column(modifier = Modifier.padding(10.dp)) {
                    Surface(
                        modifier = Modifier
                            .fillMaxWidth(0.55f)
                            .height(8.dp),
                        shape = CircleShape,
                        color = MaterialTheme.colorScheme.primary.copy(alpha = 0.28f)
                    ) {}
                    Spacer(modifier = Modifier.height(7.dp))
                    Surface(
                        modifier = Modifier
                            .fillMaxWidth(0.80f)
                            .height(6.dp),
                        shape = CircleShape,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.12f)
                    ) {}
                }
            }
            if (position == ToolbarPosition.BOTTOM) {
                Spacer(modifier = Modifier.height(7.dp))
                FakeToolbar()
            }
        }
    }
}

@Composable
private fun FakeToolbar() {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .height(34.dp),
        shape = RoundedCornerShape(11.dp),
        color = MaterialTheme.colorScheme.surface
    ) {
        Row(
            modifier = Modifier.padding(5.dp),
            horizontalArrangement = Arrangement.spacedBy(5.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Surface(
                modifier = Modifier.size(22.dp),
                shape = RoundedCornerShape(7.dp),
                color = MaterialTheme.colorScheme.surfaceVariant
            ) {}
            Surface(
                modifier = Modifier
                    .weight(1f)
                    .height(23.dp),
                shape = RoundedCornerShape(8.dp),
                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.72f)
            ) {}
            Surface(
                modifier = Modifier.size(22.dp),
                shape = RoundedCornerShape(7.dp),
                color = MaterialTheme.colorScheme.primary.copy(alpha = 0.18f)
            ) {}
        }
    }
}

